uint64_t gen_alloc(gen_heap_t gh, uint64_t wosize, uint64_t tag) {
  if (wosize <= max_young_wosize_u64) {
    uint64_t obj = minor_alloc(gh.minor, wosize, tag);
    if (obj == 0) {
      uint64_t fp = gh.fp_ref[0];
      FStar_Pervasives_Native_tuple2__uint64_uint64 res = allocate(gh.major, fp, wosize);
      gh.fp_ref[0] = FStar_Pervasives_Native_fst__t_1(res);
      return FStar_Pervasives_Native_snd__t_1(res);
    }
    else return obj;
  }
  else {
    uint64_t fp_1 = gh.fp_ref[0];
    FStar_Pervasives_Native_tuple2__uint64_uint64 res_1 = allocate(gh.major, fp_1, wosize);
    gh.fp_ref[0] = FStar_Pervasives_Native_fst__t_1(res_1);
    return FStar_Pervasives_Native_snd__t_1(res_1);
  }
}

bool minor_collect_full(gen_heap_t gh, uint64_t *roots, size_t nroots, uint64_t *fwd_arr, uint64_t *queue, uint64_t *slots, size_t nslots) {
  bool ok = cheney_promote_phase(gh.minor, gh.major, gh.fp_ref, fwd_arr, queue, roots, nroots);
  update_promoted_objects(gh.major, fwd_arr);
  rewrite_heap_slots(gh.major, fwd_arr, slots, nslots);
  size_t i = 0;
  while (i < nroots) {
    size_t iv = i;
    uint64_t r = roots[iv];
    if (r >= 8) {
      if (r < minor_heap_size_u64) {
        if ((r % 8) == 0) {
          size_t idx = (size_t)(r / 8);
          uint64_t fwd_val = fwd_arr[idx];
          if (fwd_val == 0) roots[iv] = r;
          else roots[iv] = fwd_val;
        }
        else roots[iv] = r;
      }
      else roots[iv] = r;
    }
    else roots[iv] = r;
    i = (iv + 1);
  }
  minor_heap_reset(gh.minor);
  return ok;
}

FStar_Pervasives_Native_tuple2__uint64_bool gen_gc(gen_heap_t gh, uint64_t *roots, size_t nroots, uint64_t *fwd_arr, uint64_t *queue, uint64_t *slots, size_t nslots, gray_stack_rec st) {
  bool ok = minor_collect_full(gh, roots, nroots, fwd_arr, queue, slots, nslots);
  uint64_t fp_val = gh.fp_ref[0];
  if (ok) {
    darken_roots_bounded(gh.major, st, roots, nroots);
    uint64_t final_fp = collect_with_roots(gh.major, st, fp_val);
    gh.fp_ref[0] = final_fp;
    return (FStar_Pervasives_Native_tuple2__uint64_bool){ ._1 = final_fp, ._2 = ok };
  }
  else return (FStar_Pervasives_Native_tuple2__uint64_bool){ ._1 = fp_val, ._2 = ok };
}

